card_mod.style:
 :host {
 --chip-height: 34px;
 --chip-spacing: 8px;
 --chip-font-size: 12px;
 --chip-font-weight: 600;
 --chip-background: var(--secondary-background-color);
 --chip-border-color: var(--divider-color);
 --chip-box-shadow: none;
}
ha-card {
 padding: 10px 8px;
 border: 1px solid var(--divider-color);
 border-radius: 14px;
 background: var(--ha-card-background, var(--card-background-color));
 box-shadow: none;
}
.chip-container { gap: 8px; }



:host { --chip-height: 34px; --chip-spacing: 4px; --chip-font-size: 11px; --chip-icon-size: 16px; }
.chip-container { gap: 4px; }
mushroom-template-chip:nth-child(1) { --chip-border-radius: 18px 0 0 18px; margin-inline-end: -4px; }
mushroom-template-chip:nth-child(2) { --chip-border-radius: 0; margin-inline-end: -4px; }
mushroom-template-chip:nth-child(3) { --chip-border-radius: 0 18px 18px 0; }


/* One-row status strip: labels are carried by icons, values stay compact. */
:host {
 --chip-height: 32px;
 --chip-spacing: 4px;
 --chip-font-size: 11px;
 --chip-icon-size: 16px;
 --chip-padding: 0 0.2em;
}
ha-card { padding: 8px 4px; }
.chip-container {
 display: flex !important;
 flex-wrap: nowrap !important;
 align-items: center;
 justify-content: center;
 gap: 4px !important;
}
.chip-container > * { min-width: 0; flex: 0 1 auto; }
mushroom-template-chip:nth-child(1) { --chip-border-radius: 16px 0 0 16px; margin-inline-end: -4px; }
mushroom-template-chip:nth-child(2) { --chip-border-radius: 0; margin-inline-end: -4px; }
mushroom-template-chip:nth-child(3) { --chip-border-radius: 0 16px 16px 0; }

ha-card {
  background: {{ ('url(' ~ state_attr('media_player.karthik_s_fire_tv','entity_picture') ~ ') center / cover no-repeat') if (is_state('media_player.karthik_s_fire_tv','on') and state_attr('media_player.karthik_s_fire_tv','entity_picture')) else ('linear-gradient(135deg, #56CCF2, #2F80ED)' if not is_state('media_player.karthik_s_fire_tv','off') else 'var(--ha-card-background)') }} !important;
}

:host { --primary-text-color: #ffffff; --secondary-text-color: #edf6ff; --rgb-primary-text-color: 255, 255, 255; --rgb-secondary-text-color: 237, 246, 255; }
ha-card { overflow: hidden; border-radius: 12px; border: 1px solid var(--ha-card-border-color); }
ha-card { position: relative; }
ha-card { position: relative; }

ha-card { background: transparent !important; border: none; box-shadow: none; } :host { --primary-text-color: #fff; --secondary-text-color: #edf6ff; --rgb-primary-text-color: 255,255,255; --rgb-secondary-text-color: 237,246,255; }
mushroom-state-item { padding-right: 90px; }
mushroom-state-item { padding-right: 90px; }

{% set enabled = is_state('input_boolean.bedroom_auto_climate', 'on') %}
{% set active = enabled and is_state('automation.bedroom_auto_climate', 'on') and (now().hour >= 21 or now().hour < 12) and states('sensor.lumi_lumi_sensor_ht_agl02_temperature') not in ['unknown', 'unavailable'] %}
ha-card {
  background: {{ 'linear-gradient(145deg, #eefbf7 0%, #cdeee5 100%)' if active else 'var(--ha-card-background, var(--card-background-color))' }};
  border: 1px solid {{ '#9ed7c7' if active else 'var(--divider-color)' }};
  box-shadow: {{ '0 3px 14px rgba(38, 145, 115, 0.10)' if active else 'none' }};
  {% if active %}
  --state-climate-cool-color: #258b75;
  --tile-color: #258b75;
  {% endif %}
  transition: background 300ms ease, box-shadow 300ms ease;
}

