#root { display: grid !important; grid-template-columns: repeat(2,minmax(0,1fr)) !important; grid-template-rows: repeat(3,minmax(0,1fr)) !important; gap: 8px; align-items: stretch; }
#root > :nth-child(1) { grid-column: 1 !important; grid-row: 1 / span 3 !important; }
#root > :nth-child(2) { grid-column: 2 !important; grid-row: 1 !important; }
#root > :nth-child(3) { grid-column: 2 !important; grid-row: 2 !important; }
#root > :nth-child(4) { grid-column: 2 !important; grid-row: 3 !important; }
#root > * { min-height: 0; }

:host { --grid-card-gap: 8px; }
